scripts.afterResponse:
const shortUrl = insomnia.response.text().trim();

insomnia.test('responde HTTP 201', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
});

insomnia.test('retorna URL curta com código Base62 de 6 caracteres', () => {
  insomnia.expect(shortUrl).to.match(/^https?:\/\/[^/]+\/[a-zA-Z0-9]{6}$/);
});

insomnia.test('rejeita protocolo diferente de HTTP/HTTPS com HTTP 400', () => {
  insomnia.expect(insomnia.response.code).to.eql(400);
});

insomnia.test('rejeita URL HTTP sem host com HTTP 400', () => {
  insomnia.expect(insomnia.response.code).to.eql(400);
});

const location = insomnia.response.headers.find(
  (header) => header.key.toLowerCase() === 'location'
);

insomnia.test('responde HTTP 302', () => {
  insomnia.expect(insomnia.response.code).to.eql(302);
});

insomnia.test('informa a URL original no cabeçalho Location', () => {
  insomnia.expect(location, 'cabeçalho Location').to.exist;
  insomnia.expect(location.value).to.eql('https://example.com/minha-pagina');
});

const body = JSON.parse(insomnia.response.text());

insomnia.test('responde HTTP 200', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});

insomnia.test('retorna os campos de estatísticas da URL', () => {
  insomnia.expect(body).to.have.all.keys('date', 'clickCount', 'urlOriginal');
  insomnia.expect(body.date).to.be.a('string');
  insomnia.expect(body.date).to.include('T');
  insomnia.expect(body.clickCount).to.be.a('number');
  insomnia.expect(body.clickCount).to.be.at.least(0);
  insomnia.expect(body.urlOriginal).to.eql('https://example.com/minha-pagina');
});

const body = JSON.parse(insomnia.response.text());

insomnia.test('responde HTTP 404', () => {
  insomnia.expect(insomnia.response.code).to.eql(404);
});

insomnia.test('retorna o formato esperado de erro', () => {
  insomnia.expect(body).to.have.all.keys('timestamp', 'status', 'error', 'path', 'errors');
  insomnia.expect(body.status).to.eql(404);
  insomnia.expect(body.path).to.eql('/api/url/codigo-inexistente-404');
  insomnia.expect(body.errors).to.be.an('array').that.is.not.empty;
});
